def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Join nearby separated stretches of the 9 line-art, marking the missing
    # background cells with 2. Keep all existing marks unchanged.
    for r in range(h):
        points = [c for c in range(w) if grid[r][c] == 9]
        for a, b in zip(points, points[1:]):
            if 1 <= b - a - 1 <= 8 and all(grid[r][c] == 6 for c in range(a+1, b)):
                for c in range(a+1, b):
                    out[r][c] = 2
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] == 9]
        for a, b in zip(points, points[1:]):
            if 1 <= b - a - 1 <= 8 and all(grid[r][c] == 6 for r in range(a+1, b)):
                for r in range(a+1, b):
                    out[r][c] = 2
    return out
